INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120773','Episod 30','Prompt Engineering & AI','Sediakan templat semakan laporan kewangan: kecairan, leverage, aliran tunai dan risiko; jangan beri keputusan kredit tanpa data.',NULL,'NOT TESTED','base','f2605971b3da9d40878b8a41d647d41333212cc9377b3fac3c4cca7a8e868040');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120774','Episod 1','Prompt Engineering & AI','Berdasarkan brief ini, bina spesifikasi jawapan dalam empat bahagian: matlamat, fakta tersedia, larangan dan format. Kemudian tulis penerangan 60 perkataan. Jika fakta tiada, tandakan BELUM DISAHKAN. Brief: kit mengandungi PDF dan HTML carian luar talian; jumlah prompt belum diaudit. Jangan tambah harga, jumlah atau jaminan prestasi.',NULL,'NOT TESTED','base','64704b610587092c3e77641e32ed29f5303f711a985e52d58e5bdd39c7e0cc78');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120775','Episod 2','Prompt Engineering & AI','Klasifikasikan tiga rekod ini sebagai SEDIA, TIDAK LENGKAP atau BERCANGGAH. A: Nama Kit A; harga RM20. B: Nama Kit B; harga tiada. C: Nama Kit C; harga RM20 dalam jadual dan RM25 dalam nota. Berikan label, bukti dan tindakan seterusnya. Jangan pilih sendiri harga yang bercanggah.',NULL,'NOT TESTED','base','9b6cdbf83552e73ac29d3492547155db09532394577d030d4dc60f0347767214');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120776','Episod 3','Prompt Engineering & AI','Jawab hanya menggunakan sumber: Produk dihantar sebagai PDF yang boleh dimuat turun. Soalan: Adakah pembeli menerima kemas kini percuma seumur hidup? Keluarkan jawapan, petikan bukti jika ada, dan status CUKUP BUKTI atau TIDAK CUKUP BUKTI. Jangan tafsir ketiadaan polisi sebagai ya atau tidak.',NULL,'NOT TESTED','base','545fc7ea9bcee822e6d4f06f5eb60ec4e6a39d5f393e6c2461581ecd6c46ed1b');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120777','Episod 4','Prompt Engineering & AI','Label tiket sebagai AKSES, BAYARAN atau SEMAK jika kedua-duanya hadir. Contoh: tidak boleh login → AKSES; mahu refund → BAYARAN. Klasifikasikan: Saya tidak boleh login dan mahu refund. Nyatakan frasa yang menyokong label. Jangan paksa satu kategori jika dua niat jelas.',NULL,'NOT TESTED','base','20919d11034b83e721aa894eef3c9bba370eab8648b6c1559364ba47bfee1d99');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120778','Episod 5','Prompt Engineering & AI','Ekstrak nama_produk, kuantiti, harga_unit dan jumlah_dinyatakan sebagai JSON daripada: Kit A, 2 unit, RM10 seunit, jumlah RM25. Kemudian secara berasingan semak kuantiti × harga_unit dan laporkan percanggahan. Kekalkan jumlah asal; jangan betulkan sumber secara senyap.',NULL,'NOT TESTED','base','c985f19f8917c8e14f4ba032f34403911a4d977fde51bc1e99b060e851453888');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120779','Episod 6','Prompt Engineering & AI','Tukar nota ini kepada empat bahagian: keputusan disahkan, cadangan, tindakan dengan pemilik, soalan terbuka. Nota: Ali mencadangkan pelancaran Jumaat. Siti mahu semak fail dahulu. Pasukan belum memilih tarikh. Jangan naikkan cadangan menjadi keputusan atau reka pemilik dan deadline.',NULL,'NOT TESTED','base','2b04f6ffbe00b00d3543bfc5ee9881dd8066afa234f318320b651bfe98a63858');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120780','Episod 7','Prompt Engineering & AI','Bina nota serahan daripada teks yang saya tampal selepas ini. Gunakan tajuk Matlamat, Sumber dan versi, Keputusan disahkan, Andaian, Isu terbuka, Langkah seterusnya. Jika input belum diberi, minta input. Jangan menganggap keputusan lama masih sah jika versi baharu bercanggah.',NULL,'NOT TESTED','base','fb1896b34a715d6159a7a988c628c39a0bfd6630b8172c46baff46ea0767d9e8');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120781','Episod 8','Prompt Engineering & AI','Bandingkan A: Harga RM20, akses 30 hari. B: Harga RM20, akses 90 hari. Senaraikan hanya perubahan, kesan kepada pelanggan dan perkara yang pemilik perlu sahkan. Bezakan perubahan fakta daripada gaya bahasa. Jangan anggap versi B diluluskan.',NULL,'NOT TESTED','base','ed19683ca959828a02bf478325e320a51f5175b054331f1a7c5fbafd9f0ea5ad');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120782','Episod 9','Prompt Engineering & AI','Rancang kerja 90 minit. Audit mengambil 40 minit; penulisan 30 minit selepas audit; reka bentuk 50 minit selepas penulisan. Tunjukkan jumlah masa dan jurang kapasiti. Cadangkan jadual yang boleh dilaksanakan tanpa memendekkan anggaran secara senyap. Jangan dakwa semua tugas boleh siap.',NULL,'NOT TESTED','base','38018cfe179eb1521f8e057e2fdd785b012b831f993cbf9fae97642d8eb6ccc7');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120783','Episod 10','Prompt Engineering & AI','Anda menyemak pelan pelancaran kit digital esok. Salinan jualan siap, tetapi pautan muat turun dan akses telefon belum diuji. Senaraikan tiga cara pelan boleh gagal, tanda awal, pencegahan dan pemilik tugas yang masih perlu ditetapkan. Jangan beri skor risiko palsu tanpa data.',NULL,'NOT TESTED','base','30e3b0f813f273ac0620a9d1518d4f1c7ee6848c89e890eb6b48fff91a586434');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120784','Episod 11','Prompt Engineering & AI','Nilai komposisi yang saya lampirkan dari segi pusat geometri dan berat visual. Cadangkan maksimum tiga pelarasan kecil pada jarak atau kedudukan. Jangan ubah logo. Jika tiada imej, minta imej dahulu. Terangkan sebab setiap pelarasan tanpa mendakwa koordinat tepat daripada gambar yang tidak berskala.',NULL,'NOT TESTED','base','4fadc0c81b0fad4c3b1680763af5048cbcfd13a1f882d317c275e0bb34ce84a1');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120785','Episod 12','Prompt Engineering & AI','Pendekkan ayat berikut kepada tiga pilihan tajuk maksimum enam perkataan tanpa menambah janji: Gunakan kecerdasan buatan untuk membantu menghasilkan idea kandungan yang lebih tersusun. Kekalkan maksud membantu menyusun idea. Elakkan jaminan viral atau hasil automatik.',NULL,'NOT TESTED','base','1d82b8d304913d1d375f51796b0f8db1ba63f8a9faf11431f68262a44b7b76c2');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120786','Episod 13','Prompt Engineering & AI','Bina arahan adaptasi untuk poster dengan tajuk, gambar produk, satu manfaat dan CTA. Sediakan susun atur 4:5, 1:1 dan 9:16. Nyatakan elemen wajib, yang boleh dipindah dan yang boleh dibuang. Jangan anggap resize automatik menghasilkan komposisi akhir.',NULL,'NOT TESTED','base','c51e5d0f6f536d5bad11b49fd902d49325b71ea3a84f447847c31fac466aa12f');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120787','Episod 14','Prompt Engineering & AI','Sediakan checklist praserahan cetakan Canva untuk poster. Bezakan bleed, trim dan margin selamat. Minta spesifikasi pencetak sebelum mencadangkan ukuran. Sertakan semakan PDF eksport dan proof. Jangan dakwa semua jenis dokumen Canva mempunyai kawalan cetakan yang sama.',NULL,'NOT TESTED','base','c9f44e226e8f1c27ed68bc856f7e9c6a93fb50b04aea3220a76cde928fa527dd');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120788','Episod 15','Prompt Engineering & AI','Audit imej yang saya lampirkan sebagai thumbnail. Kenal pasti elemen pertama, kedua dan ketiga yang menarik perhatian. Cadangkan satu perubahan hierarki sahaja. Jika imej tiada, minta imej. Jangan menganggap teks kecil boleh dibaca jika resolusi tidak mencukupi.',NULL,'NOT TESTED','base','ad4bb2b68e32e39387121b9b79c007c1182f501e1e4feea80c3749442b5ace5f');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120789','Episod 16','Prompt Engineering & AI','Create an original sculptural wordmark reading IDEA. Rounded letter geometry, pearl-white glossy front faces, deep blue side faces, soft studio key light from upper left, white background, generous negative space. Keep the word readable. No extra words. Treat this as an exploration, not a replacement for an existing logo.',NULL,'NOT TESTED','base','d367d1ab62d40559f17916393fec73efd181a6325b6bad5ea5937e5a82a7ddfc');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120790','Episod 17','Prompt Engineering & AI','Generate an empty white studio tabletop for a product composite. Soft key light from upper left, subtle surface texture, clean centre area, no objects, no text, no logos. Leave enough space for a tall bottle. The product will be added separately from its original photograph.',NULL,'NOT TESTED','base','316fb93064fac55de3fee54e94dd1abc3c812d0afc23f99965948940a9daafad');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120791','Episod 18','Prompt Engineering & AI','Write three image prompts for one blue ceramic cup on a white table. Keep subject, camera framing, background and material identical. Change only light direction: left, right, back. Mark the changed phrase in each prompt. Do not claim the generated outputs will be pixel-identical.',NULL,'NOT TESTED','base','f6cfdc00cbe09a5dff7b107c21c86038aa1c9ab54f52033e39fb88a212f177fd');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120792','Episod 19','Prompt Engineering & AI','Create a vertical 4:5 editorial product background. One abstract blue glass sculpture on the right third. Keep the left half white and visually quiet for a headline to be added later. Soft realistic shadows, no text, no letters, no logos.',NULL,'NOT TESTED','base','d7b49aeb18cdfbc5d6fad9f3f5a39febc85e242d22b8cb38dee622ff478f652a');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120793','Episod 20','Prompt Engineering & AI','Audit image yang saya lampirkan. Semak anatomi tangan, titik sentuhan, objek bertindih, bayang, pantulan dan teks. Berikan lokasi masalah serta sebab. Jika butiran tidak kelihatan, tandakan TIDAK DAPAT DINILAI. Jangan beri PASS untuk bahagian yang tidak dapat diperiksa.',NULL,'NOT TESTED','base','6728b4700554a9bd5044a63609d63cbee861c0c4e6110f7567b1a47383f218cc');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120794','Episod 21','Prompt Engineering & AI','Eight-second continuous shot. One adult presenter places a blue card on a white desk, then looks at the camera. Locked camera, medium framing, soft studio light, plain background. One clear action, natural hand movement. No scene change and no on-screen text.',NULL,'NOT TESTED','base','c1b66395ae241fb388f781445414f25aa02f0c029cb4db68c14fbeca0a527fd0');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120795','Episod 22','Prompt Engineering & AI','Create a continuity checklist for a fictional adult presenter: blue jacket, white shirt, watch on left wrist, white notebook. Separate fixed identity and wardrobe details from permitted changes in pose and camera angle. Include checks for hands, props and lighting. Do not promise perfect consistency from text alone.',NULL,'NOT TESTED','base','f353d4ef324ae75da7019ddc99cb3be25c6c1cdb0b49f7834a5d77ea1e906c2c');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120796','Episod 23','Prompt Engineering & AI','Plan a two-shot match cut. Shot A ends on a blue circular object centred in frame. Shot B begins with a similarly sized blue circle in the same position before revealing a new scene. Specify framing, movement direction and cut point. Label this as an editing plan, not a generated video.',NULL,'NOT TESTED','base','d07509b71be3a112dea49d721e31ab8d6b88aca5dc0c940e458f8a93d907a416');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120797','Episod 24','Prompt Engineering & AI','A fictional adult presenter stands still beside a white table. Subject movement: only a small natural head turn. Camera movement: slow forward dolly, maintaining eye-level framing. Soft studio light. No zoom, no orbit, no cuts. No on-screen text.',NULL,'NOT TESTED','base','a6efa6074115145ed474c74d9031267d16cc716299a12a1d7330f1aa339519ab');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120798','Episod 25','Prompt Engineering & AI','Build a QA checklist for an eight-second generated product video. Check first, middle and last frames, all contact events, object geometry, text, direction continuity and audio if present. Record timestamps for defects. Do not mark PASS without inspecting the actual video.',NULL,'NOT TESTED','base','cb9506b6355f7da2e630d5b8b60205dc744a1af1f9fcf16bb91f8e0eed3699d0');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120799','Episod 26','Prompt Engineering & AI','Bina jadual dakwaan dan bukti untuk produk ini: fail HTML mempunyai fungsi carian luar talian selepas dimuat turun; tiada ujian penjimatan masa. Tulis tiga hook berasaskan fakta itu sahaja. Jangan reka peratus produktiviti, jumlah pembeli atau testimoni.',NULL,'NOT TESTED','base','286170a673ab6489eb8a88143c6afddb947e74c73dee2bee1c8932194de3a7ae');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120800','Episod 27','Prompt Engineering & AI','Cadangkan tiga konsep iklan untuk fail prompt yang boleh dicari, disusun mengikut kategori dan digunakan luar talian. Setiap konsep perlu satu motivasi, satu hook, satu visual demonstrasi dan satu hipotesis ujian. Kekalkan CTA sama. Jangan mendakwa mana-mana konsep pasti menang.',NULL,'NOT TESTED','base','3acefbf2dd8672dbd83c5766c7280b436f3caaafcd323bee870b6469553c8824');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120801','Episod 28','Prompt Engineering & AI','Audit padanan mesej ini. Iklan: Cari prompt tanpa internet selepas muat turun. Landing page: Koleksi prompt besar untuk semua orang. Cadangkan headline dan demonstrasi yang menyambung janji asal tanpa menambah ciri. Nyatakan maklumat produk yang masih perlu disahkan.',NULL,'NOT TESTED','base','f952c34aaffbeefcb21002eb0bfdd2444cb949192b0eaa51159fa4f5739837ee');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120802','Episod 29','Prompt Engineering & AI','Kira kadar pembelian per klik dan kos per pembelian. A: 100 klik, 2 pembelian, belanja RM30. B: 50 klik, 3 pembelian, belanja RM30. Tunjukkan formula. Nyatakan keterbatasan sampel kecil dan jangan menyimpulkan sebab atau kepastian statistik.',NULL,'NOT TESTED','base','662bfdfbcb00dc386d782c132803cf2cc449b72cd9a828c68b22710a97a80830');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120803','Episod 30','Prompt Engineering & AI','Tulis storyboard demonstrasi ringkas untuk menjawab soalan Bagaimana saya cari prompt untuk kerja saya? Gunakan langkah buka fail HTML, cari kata kunci, pilih hasil dan salin. Nyatakan rakaman skrin sebenar yang diperlukan. Jangan reka masa carian atau memaparkan demo sebagai integrasi yang belum dibina.',NULL,'NOT TESTED','base','577b380fb68cb1d613937f3cbe57699778716195d3d7dbce64d0f071163141f6');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120804','Episod 31','Prompt Engineering & AI','Bina pelan ujian pengenalan jenama tanpa logo. Gunakan tiga visual sendiri dan tiga visual pembanding yang dibenarkan. Rawakkan urutan, tanya jenama yang diingati dan sebab. Elakkan soalan memimpin. Jelaskan bahawa sampel kecil tidak mewakili seluruh pasaran.',NULL,'NOT TESTED','base','4b85d6feb38717b2c03dc118803550f5be6e8233f463ce66b3677cb379ac2eda');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120805','Episod 32','Prompt Engineering & AI','Bina jadual token warna daripada putih #FFFFFF, Deep Ink #131321, biru #2E25D9 dan oren #F47A20. Tetapkan fungsi, contoh penggunaan dan larangan. Jangan anggap semua pasangan sesuai untuk teks kecil; tandakan pasangan yang memerlukan semakan kontras.',NULL,'NOT TESTED','base','1ea963be2da08375d64b1bcf3db13cb173d3ea4a2bb844bff08b45b7ceb1643f');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120806','Episod 33','Prompt Engineering & AI','Bina matriks penggunaan identiti untuk avatar, header, poster dan dokumen. Senaraikan aset yang diperlukan, perkara yang mesti kekal dan ujian kebolehbacaan. Jangan reka versi logo baharu; tandakan variasi yang memerlukan kelulusan pemilik.',NULL,'NOT TESTED','base','47e4363a86e24c0e964e69ce4f9a29bb3b179bb60955815c28ccd2742d67fd38');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120807','Episod 34','Prompt Engineering & AI','Bina panduan nada untuk jenama pendidikan AI. Situasi: fail gagal dimuat turun, soalan asas, dan aduan produk. Untuk setiap situasi, tulis satu respons sesuai dan satu respons yang perlu dielakkan beserta sebab. Jangan menjanjikan refund atau tempoh penyelesaian tanpa polisi.',NULL,'NOT TESTED','base','f2d5d6dfe1e4e58edc0c9d637bf18ca82f955edefcc9c97e3aa8864898aa223e');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120808','Episod 35','Prompt Engineering & AI','Reka struktur daftar aset jenama dengan medan nama aset, versi, status draf atau diluluskan, pemilik, tarikh kelulusan dan menggantikan versi. Beri tiga rekod rekaan yang jelas dilabel. Jangan menganggap aset terkini secara tarikh sudah diluluskan.',NULL,'NOT TESTED','base','ea7b2f23ea07d17973473210677b33482de0ee90f092473ae04e521525dd2b72');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120809','Episod 36','Prompt Engineering & AI','Bina aliran onboarding empat langkah untuk kit PDF, Notion dan HTML. Sasarkan pengguna baharu yang mahu menulis satu penerangan produk. Nyatakan apa yang dibuka, apa yang diisi dan bagaimana tahu langkah selesai. Jangan anggap semua format memerlukan internet atau akaun yang sama.',NULL,'NOT TESTED','base','7d3d3dd29ce64e8c884a07cf5b71f3c06d49c430e255ac6909289d965d05fdd3');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120810','Episod 37','Prompt Engineering & AI','Tulis microcopy Bahasa Melayu bagi tiga keadaan carian: input kosong, tiada padanan dan ralat sistem. Sediakan tajuk, penerangan pendek dan tindakan yang benar-benar boleh dilaksanakan. Jangan cadangkan butang atau fungsi yang belum tersedia.',NULL,'NOT TESTED','base','ef167754946c311f28b2ee192fb6d86f5e8bbcf9d40229c38b5360f7e13fb7b3');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120811','Episod 38','Prompt Engineering & AI','Cadangkan dua taksonomi untuk koleksi prompt: satu mengikut tugas, satu mengikut profesion. Gunakan contoh proposal, iklan, skrip video dan analisis jualan. Bina lima tugasan ujian pencarian serta cara merekod salah kategori. Jangan cipta keputusan pengguna.',NULL,'NOT TESTED','base','c8b1f31e75b223d772bb1adce46db4538a2f20dc18e601af36f6012adcfc176f');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120812','Episod 39','Prompt Engineering & AI','Tulis arahan kemas kini untuk produk HTML luar talian tanpa auto-update. Terangkan cara melihat versi, mendapatkan fail baharu melalui saluran rasmi dan menyimpan salinan lama jika perlu. Jangan reka pautan muat turun atau janji kemas kini percuma seumur hidup.',NULL,'NOT TESTED','base','f98ba88684753d9696390dd375a2dedb55fbce33592833dd0a0474c20322391e');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120813','Episod 40','Prompt Engineering & AI','Reka struktur kad prompt untuk penerangan produk. Medan wajib: tugas, input diperlukan, prompt, bentuk output, batasan, contoh ilustrasi dan checklist semakan. Gunakan produk rekaan tanpa harga atau dakwaan prestasi. Jangan menjanjikan hasil yang seragam bagi semua model.',NULL,'NOT TESTED','base','cde11581360600bc6732be0a0512712ad854345e9e3c9b33e9481901c4be1c62');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120814','Episod 41','Prompt Engineering & AI','Reka pseudokod penerimaan webhook pembayaran: sahkan sumber mengikut dokumentasi penyedia, padankan pesanan dan jumlah, rekod event_id secara atomik dengan unique constraint, kemudian proses penghantaran secara selamat. Terangkan keadaan duplicate dan dua request serentak. Jangan anggap prompt atau semakan frontend mencukupi.',NULL,'NOT TESTED','base','48d29b598c8bf0ca74e8959575dc9375fe2cb738f53d2e129afdf6a5f6710e8c');
